.prio-urgent { background: #de350b; color: #fff; } .prio-high { background: #ff8b00; color: #fff; }
.row { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; margin: .3rem 0; }
table { border-collapse: collapse; width: 100%; background: #fff; }
td, th { border-bottom: 1px solid #dfe1e6; padding: .3rem .5rem; text-align: left; }
.sprint { background: #fff; border-radius: 6px; padding: .75rem; margin-bottom: 1rem; }
.detail { display: grid; grid-template-columns: 2fr 1fr; gap: 1rem; }
.panel { background: #fff; border-radius: 6px; padding: 1rem; }
#notif-panel { position: fixed; right: 1rem; top: 3.2rem; width: 340px; max-height: 70vh; overflow: auto; background: #fff; border-radius: 6px; box-shadow: 0 4px 12px rgba(0,0,0,.25); padding: .5rem; z-index: 10; }
#notif-panel .unread { font-weight: bold; }
#toast { position: fixed; bottom: 1rem; left: 50%; transform: translateX(-50%); background: #de350b; color: #fff; padding: .5rem 1rem; border-radius: 4px; }
.muted { color: #5e6c84; } .error { color: #de350b; }
.comment { border-top: 1px solid #dfe1e6; padding: .5rem 0; }
pre.history { font-size: .8rem; white-space: pre-wrap; }
